var t=`0663-banga-soup`;var a=`world-0663`;var i=`NG`;var s=`western-africa`;var o=4;var r=81;var g={en:`Banga Soup`,ua:`Суп банга`};var l={en:`Banga Soup is a Nigeria classic prepared with goat meat, yellow onion, palm nut concentrate, smoked mackerel. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Суп банга, страва кухні країни Нігерія зі складниками: козлятина, жовта цибуля, концентрат пальмових плодів, копчена скумбрія. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`goat-meat`,550,`g`],[`yellow-onion`,170,`g`],[`palm-oil`,30,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`palm-nut-concentrate`,250,`g`],[`water`,850,`ml`],[`smoked-mackerel`,190,`g`],[`crayfish`,120,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`spinach`,170,`g`],[`table-salt`,null,`to_taste`]]}];var u={slug:t,id:a,country:`NG`,region:s,servings:4,minutes:81,title:g,text:l,steps:m};export{i as country,u as default,a as id,r as minutes,s as region,o as servings,t as slug,m as steps,l as text,g as title};